#!/usr/bin/env bash
set -euo pipefail
ucr_meta_muse_prepare_env(){ local model="$1"; local token="${META_MODEL_API_KEY:-${META_API_KEY:-}}"; [[ -n "$token" ]] || { printf '[UCR][BLOCKED] Meta credential is missing\n' >&2; return 78; }; export ANTHROPIC_BASE_URL='https://api.meta.ai' ANTHROPIC_AUTH_TOKEN="$token" ANTHROPIC_MODEL="$model" ANTHROPIC_DEFAULT_OPUS_MODEL="$model" ANTHROPIC_DEFAULT_SONNET_MODEL="$model" ANTHROPIC_DEFAULT_HAIKU_MODEL="$model" CLAUDE_CODE_SUBAGENT_MODEL="$model" UCR_ACTIVE_PROVIDER=meta-muse UCR_ACTIVE_MODEL="$model"; unset ANTHROPIC_API_KEY CLAUDE_CODE_USE_BEDROCK AWS_BEARER_TOKEN_BEDROCK AWS_REGION; }
